              'Η διευθύντρια Πολιτισμού Μηχανικής της Google Cloud, Δρ Πρίγια Σάρμα, ανέλαβε να δημιουργήσει ένα αξέχαστο πρόγραμμα ομαδοποίησης για 1.200 μηχανικούς λογισμικού σε 6 τοποθεσίες γραφείων στη Βόρεια Αμερική. Οι παραδοσιακές εκδηλώσεις εκτός γραφείου σε αίθουσες συνεδριών και τα escape rooms είχαν φθίνουσες βαθμολογίες εμπλοκής (μέσος όρος 3,1/5). Η Δρ Σάρμα ήθελε μια υπαίθρια δραστηριότητα που προωθούσε τη συνεργασία, συμπεριλάμβανε όλα τα επίπεδα φυσικής κατάστασης και ενίσχυε το μήνυμα της Google Cloud build, connect, scale. Είχε προϋπολογισμό 400 χιλιάδων δολαρίων ΗΠΑ για ένα πρόγραμμα του καλοκαιριού 2025 και χρειαζόταν μια λύση κλειδιά στο χέρι που να περιλαμβάνει επωνυμία, εξοπλισμό, εκπαίδευση και διαχείριση ασφάλειας.',
            goal: 'Σχεδιασμός και εκτέλεση επεκτάσιμου προγράμματος ομαδοποίησης SUP για 1.200 μηχανικούς της Google Cloud σε 6 τοποθεσίες με συμμετοχή πάνω από 90%, επίτευξη Net Promoter Score 4,5/5 και παραμονή εντός του προϋπολογισμού των 400 χιλιάδων δολαρίων ΗΠΑ.',
