                'Τον Σεπτέμβριο του 2024, η Ουαμάν συνεργάστηκε με τη περιβαλλοντική ερευνητική διαίρεση της Afarer για να προσαρμόσει το EcoTouring 12 ποδιών και 6 ιντσών X για ανάπτυξη επιστημονικού φορτίου. Οι τροποποιήσεις περιλάμβαναν ενισχυμένη πλάκα τοποθέτησης καταστρώματος (ανοξείδωτο ατσάλι, διάταξη 4 βιδών) για καθοδηγητή ψαριών/σόναρ Garmin echoMAP Plus 74cv, ένα ενσωματωμένο σύστημα RAM-mount για GoPro HERO12 Black σε υποβρύχια θήκη, ένα στεγανό φρεάτιο εξοπλισμού (όγκος 7 λίτρων, βιδωτή στεγανοποίηση) μέσα στον πυρήνα της σανίδας για καταγραφείς δεδομένων και ανιχνευτές GPS και μια χαμηλού προφίλ προστασία καρίνης που επέτρεπε την προσάραξη σε λασπώδεις όχθες ποταμού. Τρία πρωτότυπα δοκιμάστηκαν στον Ουκαγιάλι τον Οκτώβριο του 2024, με μέτρηση υποβρύχιου θορύβου στα 18 dB (έναντι 52 dB για εξωλέμβιο Tohatsu 25 ίππων στα 5 μ.). Ο ARA παρήγγειλε 18 σανίδες με 212 χιλ. δολάρια ΗΠΑ, χρηματοδοτούμενα από το Ίδρυμα Gordon και Betty Moore.',
