                'Τον Μάιο του 2024, η ομάδα ακραίων περιβαλλόντων της Afarer (ο επικεφαλής μηχανικός Σβεν Λέμαν από το γραφείο της Afarer στο Αμβούργο) συνόδευσε το MS Maud της Hurtigruten σε μια κρουαζιέρα 14 ημερών στη Σβάλμπαρ. Δοκίμασαν 8 ανταγωνιστικές σανίδες και 6 πρωτότυπα Afarer Arctic σε 11 αναπτύξεις Zodiac κοντά στο Νι-Ολεσούν και τον Παγετώνα Μονακό. Βασικά ευρήματα: οι τυποποιημένες βαλβίδες πάγωναν ανοιχτές σε αέρα -8 °C μετά την εμβάπτιση σε νερό 2 °C (το ζεστό νερό μέσα στον στύλο της βαλβίδας ξαναπάγωνε σε επαφή με τον κρύο αέρα). Η λύση της Afarer: ένα σύστημα βαλβίδας καθαρισμού με άζωτο που απομάκρυνε όλη την υγρασία πριν το κλείσιμο, συν ένα νεοπρένιο κάλυμμα βαλβίδας. Υλικό σανίδας: το τυποποιημένο PVC έχανε 40% της ευλυγισίας στους -15 °C — ο συνδυασμός Polarex TPU της Afarer διατηρούσε 92% ευλυγισία στους -20 °C. Οι σανίδες έπρεπε να φουσκώνουν σε λιγότερο από 7 λεπτά (το όριο υπομονής των επισκεπτών σε κρύες συνθήκες) και να ξεφουσκώνουν και να πακετάρονται σε 5 λεπτά (για ελαχιστοποίηση του παραθύρου έκθεσης σε πολικές αρκούδες). Η αντλία 2 σταδίων της Afarer (χειροκίνητη αντλία για τα πρώτα 10 PSI, ενισχυτής φυσιγγίου αζώτου έως τα 18 PSI) πέτυχε φούσκωμα σε 6,2 λεπτά.',
